// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 firstHash, bytes32 secondHash, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(uint256(secondHash) != 0);

        // lock an initial guess (any hash)
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(firstHash);

        // advance past the locked block so settle is admissible
        vm.roll(block.number + 2);

        bool settled;
        vm.prank(actor);
        try c.settle() { settled = true; } catch { settled = false; }

        // RULE: once settled, the caller's slot is freed, so locking a NEW
        // guess must succeed for every admissible input.
        bool canRelock;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(secondHash) { canRelock = true; } catch { canRelock = false; }

        assertTrue(settled == false || canRelock, "after settle, a new guess must be lockable");
    }
}
